// Board: the front end, on real data.
// A horizontal kanban of a Notion database. An SVG draws each card.
// Real Buttons and Links are laid over the SVG: move left, block, move right, open Notion, open the PR.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BoardCard } from '../types'

const PANE = 'board'
// The id of your Notion connector, and the collection:// id of your database.
