const NOTION_PATH =
  'M4.459 4.208c.746.606 1.026.56 2.428.466l13.215-.793c.28 0 .047-.28-.046-.326L17.86 1.968c-.42-.326-.981-.7-2.055-.607L3.01 2.295c-.466.046-.56.28-.374.466zm.793 3.08v13.904c0 .747.373 1.027 1.214.98l14.523-.84c.841-.046.935-.56.935-1.167V6.354c0-.606-.233-.933-.748-.887l-15.177.887c-.56.047-.747.327-.747.933zm14.337.745c.093.42 0 .84-.42.888l-.7.14v10.264c-.608.327-1.168.514-1.635.514-.748 0-.935-.234-1.495-.933l-4.577-7.186v6.952L12.21 19s0 .84-1.168.84l-3.222.186c-.093-.186 0-.653.327-.746l.84-.233V9.854L7.822 9.76c-.094-.42.14-1.026.793-1.073l3.456-.233 4.764 7.279v-6.44l-1.215-.139c-.093-.514.28-.887.747-.933zM1.936 1.035l13.31-.98c1.634-.14 2.055-.047 3.082.7l4.249 2.986c.7.513.934.653.934 1.213v16.378c0 1.026-.373 1.634-1.68 1.726l-15.458.934c-.98.047-1.448-.093-1.962-.747l-3.129-4.06c-.56-.747-.793-1.306-.793-1.96V2.667c0-.839.374-1.54 1.447-1.632z'

const SAMPLE: BoardCard[] = [
  { id: 's1', url: 'https://www.notion.so', job: 101, title: 'Sample: payments ledger', pri: 'P1', owner: 'Sample', status: 'Needs Built', pr: '' },
  { id: 's2', url: 'https://www.notion.so', job: 102, title: 'Sample: <b> & "quotes"', pri: 'P0', owner: 'Sample', status: 'In progress', pr: 'https://github.com' },
  { id: 's3', url: 'https://www.notion.so', job: 103, title: 'Sample: time tracking', pri: 'P2', owner: 'Sample', status: 'Blocked', pr: '' },
  { id: 's4', url: 'https://www.notion.so', job: 104, title: 'Sample: shipped job', pri: 'P2', owner: 'Sample', status: 'Done', pr: 'https://github.com' },
]

const cards = atom({ plugin: 'board', key: 'cards' } as const, [])
const note = atom({ plugin: 'board', key: 'note' } as const, 'Loading from Notion...')

function esc(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function cut(s: string, n: number): string {
  return s.length > n ? `${s.slice(0, Math.max(1, n - 1))}…` : s
}

function wrapTitle(title: string, perLine: number, max: number): string[] {
  const lines: string[] = []
  let line = ''
  for (const word of title.split(' ')) {
    if (line && `${line} ${word}`.length > perLine) {
      lines.push(line)
      line = word
    } else {
      line = line ? `${line} ${word}` : word
    }
  }
  if (line) lines.push(line)
  const kept = lines.slice(0, max)
  if (lines.length > max) kept[max - 1] = `${kept[max - 1]}…`
  return kept.map(l => cut(l, perLine + 1))
}

// Braille blank: text that draws nothing, so the Link over a logo shows only the logo.
const BLANK = '\u2800\u2800\u2800'

function iconSvg(path: string, fill: string, label: string, box = 24): string {
  return `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24"><title>${label}</title><rect width="24" height="24" rx="6" fill="#F0F6FC"/><g transform="translate(3 3) scale(${(18 / box).toFixed(4)})"><path fill="${fill}" d="${path}"/></g></svg>`
}

// The look of one card. The top holds the job number and the title.
// The lower part is left free: the buttons and links are laid over it.
function cardSvg(c: BoardCard, W: number, col: number): string {
  const stripe = COLORS[col] ?? '#8B949E'
  const pri = c.pri === 'P0' ? '#F85149' : c.pri === 'P1' ? '#FF7235' : '#6E7681'
  const perLine = Math.max(6, Math.floor((W - 12) / 5.6))
  const text = wrapTitle(c.title, perLine, 2)
    .map((l, i) => `<text x="7" y="${33 + i * 12}" font-family="system-ui, sans-serif" font-size="10" font-weight="600" fill="#F0F6FC">${esc(l)}</text>`)
    .join('')
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${CARD_H}" viewBox="0 0 ${W} ${CARD_H}">
  <rect x="0.5" y="0.5" width="${W - 1}" height="${CARD_H - 1}" rx="8" fill="#1C2026" stroke="#30363D"/>
  <rect x="8" y="0" width="${W - 16}" height="3" rx="1.5" fill="${stripe}"/>
  <rect x="6" y="9" width="22" height="11" rx="5.5" fill="${pri}"/>
  <text x="17" y="17.5" font-family="system-ui, sans-serif" font-size="8" font-weight="700" fill="#fff" text-anchor="middle">${esc(c.pri || '-')}</text>
  <text x="${W - 7}" y="18" font-family="system-ui, sans-serif" font-size="9" fill="#9BA3AD" text-anchor="end">#${c.job}</text>
  ${text}
  <rect x="7" y="53" width="${W - 14}" height="1" fill="#30363D"/>
</svg>`
}

function pageId(url: string): string {
  const m = /([0-9a-f]{32})(?:\?|$)/i.exec(url.replace(/-/g, ''))
  return m ? m[1] : ''
}

function rank(p: string): number {
  return p === 'P0' ? 0 : p === 'P1' ? 1 : p === 'P2' ? 2 : 3
}

type Row = { url?: string; Name?: string; Workstream?: string; Priority?: string; Owner?: string; PR?: string; 'Job ID'?: number }

async function query($: EngineInterface, where: string, tail: string): Promise<BoardCard[]> {
  const res = await $.mcp.call(NOTION, 'notion-query-data-sources', {
    data: {
      mode: 'sql',
      data_source_urls: [SOURCE],
      query: `SELECT url, "Name", "Workstream", "Priority", "Owner", "PR", "Job ID" FROM "${SOURCE}" WHERE ${where} ${tail}`,
    },
  })
  const first = (res.content as { text?: string }[] | undefined)?.[0]?.text ?? ''
  if (res.isError) throw new Error(cut(first || 'Notion returned an error', 140))
  const rows = (JSON.parse(first) as { results?: Row[] }).results ?? []
  return rows.map(r => ({
    id: pageId(String(r.url ?? '')),
    url: String(r.url ?? ''),
    job: Number(r['Job ID'] ?? 0),
    title: String(r.Name ?? '').replace(/^Job\s+\d+\s*[—–-]\s*/, ''),
    pri: String(r.Priority ?? ''),
    owner: String(r.Owner ?? ''),
    status: String(r.Workstream ?? ''),
    pr: String(r.PR ?? ''),
  }))
}

async function sync($: EngineInterface) {
  try {
    const open = await query($, `"Workstream" IN ('Needs Built','In progress','Needs Checked','Blocked','Held')`, 'LIMIT 100')
    const done = await query($, `"Workstream" = 'Done'`, 'ORDER BY "Job ID" DESC LIMIT 6')
    await update($, cards, () => [...open, ...done])
    await update($, note, () => `Synced with Notion at ${new Date().toLocaleTimeString()}`)
  } catch (err) {
    await update($, note, () => `Could not read Notion. ${cut(String(err), 120)}`)
  }
}

async function setStatus($: EngineInterface, id: string, status: string) {
  const list = (await read($, cards)) as BoardCard[]
  const card = list.find(c => c.id === id)
  if (!card || card.status === status) return
  const before = card.status
  await update($, cards, () => list.map(c => (c.id === id ? { ...c, status } : c)))
  if (id.startsWith('s')) return
  try {
    const res = await $.mcp.call(NOTION, 'notion-update-page', {
      page_id: id,
      command: 'update_properties',
      allow_async: false,
      properties: { Workstream: status },
    })
    if (res.isError) throw new Error('Notion refused the change')
    await update($, note, () => `Job ${card.job} moved to ${status} in Notion`)
  } catch (err) {
    const now = (await read($, cards)) as BoardCard[]
    await update($, cards, () => now.map(c => (c.id === id ? { ...c, status: before } : c)))
    await update($, note, () => `Job ${card.job} did not move. ${cut(String(err), 100)}`)
  }
}

async function step($: EngineInterface, id: string, dir: number) {
  const list = (await read($, cards)) as BoardCard[]
  const card = list.find(c => c.id === id)
  if (!card) return
  const at = FLOW.indexOf(card.status)
  const to = Math.max(0, Math.min(FLOW.length - 1, (at < 0 ? 0 : at) + dir))
  await setStatus($, id, FLOW[to] ?? FLOW[0])
}

async function loadSample($: EngineInterface) {
  await update($, cards, () => SAMPLE)
  await update($, note, () => 'Sample cards. They are not in Notion.')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'board', description: 'Open the Board pane (Notion kanban)' })
    void sync($)
    $.clock.every(300000, () => {
      void sync($)
    })
    void $.ui.open({ id: PANE, title: 'Board' })
    return next(e)
  })

  on('command.run', { command: 'board' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Board' })
    void sync($)
    return { text: 'Board pane opened.' }
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text, Button, Link, Svg } = $.ui.resolve(e) as Record<string, any>
    const list = (await read($, cards)) as BoardCard[]
    const status = String(await read($, note))
    const hasSvg = e.surface !== 'terminal'
    const bodyColumns = Number(e.props.bodyColumns) || 51
    const colCells = Math.max(9, Math.floor((bodyColumns - (FLOW.length - 1)) / FLOW.length))
    const cardPx = Math.round(colCells * PX_PER_CELL)
    const parked = list.filter(c => PARKED.includes(c.status))
    const sorted = (i: number) =>
      list
        .filter(c => c.status === FLOW[i])
        .sort((a, b) => (i === FLOW.length - 1 ? b.job - a.job : rank(a.pri) - rank(b.pri) || a.job - b.job))
    const logo = (path: string, fill: string, name: string, box: number, href: string) =>
      hasSvg ? (
        <Box>
          <Svg source={iconSvg(path, fill, name, box)} alt={`${name} logo`} width={16} height={16} />
          <Box position="absolute" top={0} left={0}>
            <Link href={href} label={BLANK} />
          </Box>
        </Box>
      ) : (
        <Link href={href} label={name} />
      )
    const controls = (c: BoardCard, i: number) => (
      <Box flexDirection="column">
        <Box flexDirection="row" flexWrap="wrap">
          {i > 0 ? <Button key={`l-${c.id}`} label="⬅️" onPress={() => step($, c.id, -1)} /> : null}
          <Button key={`b-${c.id}`} label="🛑" onPress={() => setStatus($, c.id, 'Blocked')} />
          {i < FLOW.length - 1 ? <Button key={`r-${c.id}`} label="➡️" onPress={() => step($, c.id, 1)} /> : null}
        </Box>
        <Box flexDirection="row" columnGap={1} alignItems="center">
          {logo(NOTION_PATH, '#000000', 'Notion', 24, c.url)}
          {c.pr.startsWith('https://') ? logo(GITHUB_PATH, '#181717', 'GitHub', GITHUB_BOX, c.pr) : null}
        </Box>
      </Box>
    )
    return (
      <Box flexDirection="column" gap={1}>
        {list.length === 0 ? <Button key="sample" plain label="Load sample cards" onPress={() => loadSample($)} /> : null}
        <Box flexDirection="row" columnGap={1}>
          {FLOW.map((name, i) => {
            const mine = sorted(i)
            return (
              <Box flexDirection="column" width={colCells} rowGap={1}>
                <Text bold color={THEME[i]} wrap="truncate-end">
                  {SHORT[i]} <Text dimColor>{mine.length}</Text>
                </Text>
                {mine.length === 0 ? <Text dimColor>none</Text> : null}
                {mine.slice(0, PER_COLUMN).map(c =>
                  hasSvg ? (
                    <Box key={`card-${c.id}`} flexDirection="column">
                      <Svg source={cardSvg(c, cardPx, i)} alt={`Job ${c.job}: ${c.title}`} width={cardPx} height={CARD_H} />
                      <Box position="absolute" top={3} left={1}>
                        {controls(c, i)}
                      </Box>
                    </Box>
                  ) : (
                    <Box key={`card-${c.id}`} flexDirection="column" borderStyle="round" borderColor={THEME[i]}>
                      <Text wrap="wrap">
                        #{c.job} {c.title}
                      </Text>
                      {controls(c, i)}
                    </Box>
                  ),
                )}
                {mine.length > PER_COLUMN ? <Text dimColor>+{mine.length - PER_COLUMN} more</Text> : null}
              </Box>
            )
          })}
        </Box>
        {parked.length ? (
          <Box flexDirection="column">
            <Text bold color="error">
              Blocked or held <Text dimColor>{parked.length}</Text>
            </Text>
            {parked.map(c => (
              <Box flexDirection="row" columnGap={1} flexWrap="wrap">
                <Button key={`u-${c.id}`} label="➡️" onPress={() => setStatus($, c.id, 'Needs Built')} />
                <Text wrap="truncate-end">
                  #{c.job} {c.title}
                </Text>
              </Box>
            ))}
          </Box>
        ) : null}
        <Box flexDirection="row" columnGap={1} alignItems="center">
          <Button key="refresh" plain label="↻" onPress={() => sync($)} />
          <Text dimColor wrap="truncate-end">
            {status}
          </Text>
        </Box>
      </Box>
    )
  })
}

